document.addEventListener("DOMContentLoaded", () => {
import("./crew-member.js").then((module) => {
    const CrewMember = module.default;
    const nova = new CrewMember({ name: "Nova", role: "Navigator" });
    const deneb = new CrewMember({ name: "Deneb", role: "Cook" });
    console.log("test: " + nova.describe() + " / " + deneb.describe());
    console.log("test: describe is " + (Object.keys(nova).includes("describe") ? "copied into each one" : "shared by the class"));
  })
  .catch((error) => console.log("test: failed " + error.message));
});

