export default class CrewMember {
  constructor({ name, role }) {
    this.name = name;
    this.role = role;
  }

  describe() {
    return "Described by the test: " + this.name;
  }

  isInCharge() {
    return false;
  }

  get callSign() {
    return "TST";
  }
}
